class Solution {
    private boolean hidden(String w, String text) {
        int i = 0;
        for (int t = 0; t < text.length() && i < w.length(); t++) if (text.charAt(t) == w.charAt(i)) i++;
        return i == w.length();
    }

    public String longestByDeleting(String text, String[] dictionary) {
        String[] order = dictionary.clone();
        Arrays.sort(order, (a, b) -> a.length() != b.length() ? b.length() - a.length() : a.compareTo(b));
        for (String w : order) if (hidden(w, text)) return w;
        return "";
    }
}

