static bool hidden(const char* w, const char* text) {
    for (; *text && *w; text++) if (*text == *w) w++;
    return *w == '\0';
}

static int prefer(const void* x, const void* y) {
    const char *a = *(char* const*) x, *b = *(char* const*) y;
    size_t la = strlen(a), lb = strlen(b);
    return la != lb ? (lb > la) - (lb < la) : strcmp(a, b);
}

char* longestByDeleting(char* text, char** dictionary, int dictionarySize) {
    char** order = malloc(dictionarySize * sizeof(char*));
    memcpy(order, dictionary, dictionarySize * sizeof(char*));
    qsort(order, dictionarySize, sizeof(char*), prefer);
    const char* best = "";
    for (int k = 0; k < dictionarySize; k++) if (hidden(order[k], text)) { best = order[k]; break; }
    free(order);
    char* out = malloc(strlen(best) + 1);
    strcpy(out, best);
    return out;
}

