    for (; *text && *w; text++) if (*text == *w) w++;
    return *w == '\0';
}

char* longestByDeleting(char* text, char** dictionary, int dictionarySize) {
    const char* best = "";
    size_t bestLen = 0;
    for (int k = 0; k < dictionarySize; k++) {
        size_t len = strlen(dictionary[k]);
        int wins = len > bestLen || (len == bestLen && strcmp(dictionary[k], best) < 0);
        if (wins && hidden(dictionary[k], text)) { best = dictionary[k]; bestLen = len; }
    }
    char* out = malloc(bestLen + 1);
    strcpy(out, best);
    return out;
}
